<?php require '../../includes/config.php';require '../../includes/layout.php';require_login(['student']);$uid=$_SESSION['user']['id'];$ref=$_GET['ref']??'';$stmt=$conn->prepare('SELECT t.*,d.name department_name FROM tickets t LEFT JOIN departments d ON d.id=t.department_id WHERE t.ref_number=? AND t.student_id=? LIMIT 1');$stmt->bind_param('si',$ref,$uid);$stmt->execute();$ticket=$stmt->get_result()->fetch_assoc();if(!$ticket){http_response_code(404);die('Ticket not found.');}$updates=[];$stmt=$conn->prepare('SELECT u.message,u.created_at,x.full_name FROM ticket_updates u LEFT JOIN users x ON x.id=u.user_id WHERE ticket_id=? ORDER BY u.created_at ASC');$stmt->bind_param('i',$ticket['id']);$stmt->execute();$updates=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);student_shell('Ticket Details','tickets');?><div class="page-header"><h2><?=e($ticket['ref_number'])?></h2></div><div class="content-card"><p><b>Status:</b> <?=e($ticket['status'])?> &nbsp; <b>Department:</b> <?=e($ticket['department_name']?:'Pending administration routing')?></p><h3><?=e($ticket['subject'])?></h3><p><b>Type:</b> <?=e($ticket['category'])?> | <b>Topic:</b> <?=e($ticket['topic'])?></p><p><?=nl2br(e($ticket['description']))?></p><?php if($ticket['resolution'])echo'<h4>Resolution</h4><p>'.nl2br(e($ticket['resolution'])).'</p>';?></div><div class="content-card"><h3>Updates</h3><?php if(!$updates)echo'<p>No updates yet.</p>';foreach($updates as $u)echo'<div style="border-bottom:1px solid #eee;padding:10px 0"><b>'.e($u['full_name']?:'Support Team').'</b><small style="float:right">'.e(date('d M Y H:i',strtotime($u['created_at']))).'</small><p>'.nl2br(e($u['message'])).'</p></div>';?></div><?php dashboard_footer(); ?>